package e.e.a;
import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicInteger;
/** The same expectations are executed on both the original and corrected classes. */
public final class BeforeAfterReproTest {
 static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
 static class Connection extends HttpURLConnection {
  final AtomicInteger reads;byte[] body="<meta name=\"server-response\" content=\"{}\">".getBytes(StandardCharsets.UTF_8);long closeDelay;volatile boolean closed;
  Connection(AtomicInteger reads)throws Exception{super(new URL("https://www.nicovideo.jp/search/repro"));this.reads=reads;}
  public InputStream getInputStream()throws IOException{reads.incrementAndGet();try{Thread.sleep(80);}catch(InterruptedException ex){Thread.currentThread().interrupt();throw new InterruptedIOException();}return new ByteArrayInputStream(body);}
  public void connect(){}public boolean usingProxy(){return false;}public void disconnect(){try{Thread.sleep(closeDelay);}catch(InterruptedException ex){Thread.currentThread().interrupt();}closed=true;}
 }
 static void consume(Connection c)throws Exception{try(InputStream in=PageCache.input(c)){byte[] b=new byte[4096];while(in.read(b)!=-1){}}}
 static void shared()throws Exception{PageCache.refresh();ExecutorService pool=Executors.newFixedThreadPool(8);AtomicInteger reads=new AtomicInteger();CountDownLatch ready=new CountDownLatch(8);try{List<Future<?>> all=new ArrayList<>();for(int i=0;i<8;i++)all.add(pool.submit(()->{ready.countDown();ready.await();consume(new Connection(reads));return null;}));for(Future<?> f:all)f.get(5,TimeUnit.SECONDS);System.out.println("requests="+reads);check(reads.get()==1,"duplicate simultaneous page reads");}finally{pool.shutdownNow();}}
 static void auth()throws Exception{PageCache.refresh();AtomicInteger reads=new AtomicInteger();Connection a=new Connection(reads),b=new Connection(reads);a.setRequestProperty("Cookie","user_session=A");b.setRequestProperty("Cookie","user_session=B");consume(a);consume(b);System.out.println("account_scoped_requests="+reads);check(reads.get()==2,"account-specific request served from another cookie scope");}
 static void queue()throws Exception{ThreadPoolExecutor pool=new ThreadPoolExecutor(1,1,0,TimeUnit.SECONDS,new LinkedBlockingQueue<>());CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);try{pool.execute(()->{entered.countDown();try{release.await();}catch(InterruptedException ex){Thread.currentThread().interrupt();}});entered.await();List<NetworkTask> tasks=new ArrayList<>();for(int i=0;i<1000;i++){NetworkTask t=new NetworkTask();t.start(pool,()->{});tasks.add(t);}for(NetworkTask t:tasks)t.cancel();int n=pool.getQueue().size();System.out.println("retained_cancelled_tasks="+n);check(n==0,"cancelled queued tasks retain request closures");}finally{release.countDown();pool.shutdownNow();}}
 static void late()throws Exception{NetworkTask t=new NetworkTask();t.cancel();Connection c=new Connection(new AtomicInteger());c.closeDelay=300;long at=System.nanoTime();check(!t.bind(c),"cancelled bind accepted");long ms=TimeUnit.NANOSECONDS.toMillis(System.nanoTime()-at);System.out.println("bind_caller_ms="+ms);check(ms<150,"disconnect blocks late-bind caller");long until=System.nanoTime()+TimeUnit.SECONDS.toNanos(3);while(!c.closed&&System.nanoTime()<until)Thread.yield();check(c.closed,"late connection not released");}
 public static void main(String[] args)throws Exception{switch(args[0]){case "shared":shared();break;case "auth":auth();break;case "queue":queue();break;case "late":late();break;default:throw new IllegalArgumentException();}System.out.println("PASS "+args[0]);}
}
